@pytest.mark.usefixtures('clean_system', 'remove_additional_folders')
def test_empty_hooks():
    # Empty hooks should now work successfully (do nothing) rather than
    # failing with a cryptic Exec format error.
    # OSError.errno=8 is not thrown on Windows when the script is empty
    # because it always runs through shell instead of needing a shebang.

    if not sys.platform.startswith('win'):
        # On Unix-like systems, empty hooks should now succeed
        generate.generate_files(
            context={
                'cookiecutter': {'shellhooks': 'shellhooks'}
            },
            repo_dir='tests/test-shellhooks-empty/',
            overwrite_if_exists=True
        )
        # No exception should be raised - empty hook should execute successfully
    else:
        # On Windows, empty hooks run through shell and should succeed
        generate.generate_files(
            context={
                'cookiecutter': {'shellhooks': 'shellhooks'}
            },
